f@prog = f@letterNum - f@curveu2 - f@count - chf("ramp");

if (f@prog < 0 ) {
    removepoint(0,@ptnum);
}

int all_prims[] = expandprimgroup(0, "*");

float runningVal = 0;

for (int i = 0; i < len(all_prims); i++) {
    setprimattrib(0, "count", all_prims[i], runningVal);
    runningVal += 1.0 + rand(i);
}

int prim_num = 1;
vector prim_uv = {0,0,0};
float max_dist = 0.01;

f@mask = 1.0-chramp("dist", chf("width")* xyzdist(1, v@P, prim_num, prim_uv, max_dist) );
f@flatten = primuv(1, "flatten", prim_num, prim_uv);
v@Cd = lerp({1,1,1}, {1,0,0}, f@flatten * f@mask);


v@P += chf("raiseHeight") * v@N * f@mask * (0.7 + @flatten);
